import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./SettingsPage.css";

function SettingsPage() {
  const navigate = useNavigate();

  // Load settings from localStorage
  const [notifications, setNotifications] = useState(
    JSON.parse(localStorage.getItem("notifications")) ?? true
  );
  const [theme, setTheme] = useState(localStorage.getItem("theme") || "light");

  useEffect(() => {
    // Apply theme to body
    document.body.className = "";
    document.body.classList.add(theme === "dark" ? "dark-theme" : "light-theme");
  }, [theme]);

  // Save settings
  const handleSaveSettings = () => {
    localStorage.setItem("notifications", notifications);
    localStorage.setItem("theme", theme);
    alert("Settings saved!");
  };

  // Change password (mocked with localStorage)
  const handleChangePassword = () => {
    const storedPassword = localStorage.getItem("userPassword"); // password stored during signup
    const oldPassword = prompt("Enter your current password:");
    if (!oldPassword) return;

    if (oldPassword !== storedPassword) {
      alert("Old password is incorrect!");
      return;
    }

    const newPassword = prompt("Enter your new password:");
    if (!newPassword) return;

    localStorage.setItem("userPassword", newPassword);
    alert("Password updated successfully!");
  };

  return (
    <div className="settings-container">
      {/* Sidebar */}
      <div className="settings-sidebar">
        <h2>Menu</h2>
        <button onClick={() => navigate("/home")}>Home</button>
        <button onClick={() => navigate("/profile")}>Profile</button>
        <button onClick={() => navigate("/settings")}>Settings</button>
        <button onClick={() => navigate("/about")}>About</button>
        <button
          onClick={() => {
            localStorage.removeItem("user");
            navigate("/");
          }}
        >
          Logout
        </button>
      </div>

      {/* Main Content */}
      <div className="settings-main">
        <h1>Settings</h1>

        <div className="settings-card">
          <h2>Account Settings</h2>
          <p>Change your password, update email, or manage account info.</p>
          <button className="settings-btn" onClick={handleChangePassword}>
            Change Password
          </button>
        </div>

        <div className="settings-card">
          <h2>Notifications</h2>
          <p>Enable or disable notifications for your account.</p>
          <label className="switch">
            <input
              type="checkbox"
              checked={notifications}
              onChange={() => setNotifications(!notifications)}
            />
            <span className="slider round"></span>
          </label>
        </div>

        <div className="settings-card">
          <h2>Theme</h2>
          <p>Select your preferred theme.</p>
          <select
            value={theme}
            onChange={(e) => setTheme(e.target.value)}
            className="theme-select"
          >
            <option value="light">Light</option>
            <option value="dark">Dark</option>
          </select>
        </div>

        <button className="settings-btn" onClick={handleSaveSettings}>
          Save Settings
        </button>

        <button className="back-btn" onClick={() => navigate("/home")}>
          Back to Home
        </button>
      </div>
    </div>
  );
}

export default SettingsPage;
